"""Search keywords, generated by the LLM from ``brand.txt``.

Keywords are never typed by hand: ``brand.txt`` is the only niche input. The
generator may also read, as extra context, phrases from the latest
``out/comments-*.txt`` and titles of relevant videos in the latest scout output.
Each generation rewrites ``keywords.generated.txt`` (``language | keyword`` per
line) so the user can see what gets searched.

Searches are the expensive call, so each run picks the keywords searched least
recently (``state/keywords.json``).
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path

from .config import Config
from .errors import ScoutError
from .llm import LLM, object_schema
from .state import read_json, utc_now, write_json, write_text

MAX_CONTEXT_LINES = 40

SYSTEM = (
    "You write YouTube search queries that find small, recently active channels in a niche. "
    "Write the short phrases a creator in the niche would put in a video title, or a viewer would "
    "type into YouTube search: concrete topics, techniques, formats and tools. Avoid generic "
    "single words, brand-new slang you are unsure of, and anything aimed at children."
)


@dataclass(frozen=True)
class Keyword:
    language: str
    text: str


def latest_file(directory: Path, pattern: str) -> Path | None:
    files = sorted(directory.glob(pattern)) if directory.exists() else []
    return files[-1] if files else None


def comment_phrases(cfg: Config) -> list[str]:
    path = latest_file(cfg.out_dir, "comments-*.txt")
    if not path:
        return []
    phrases = []
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.startswith("#") or "\t" not in line:
            continue
        phrases.append(line.split("\t", 1)[1].strip())
    return phrases[:MAX_CONTEXT_LINES]


def relevant_titles(cfg: Config) -> list[str]:
    path = latest_file(cfg.out_dir, "[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9].json")
    if not path:
        return []
    data = json.loads(path.read_text(encoding="utf-8"))
    titles = [t for channel in data.get("channels", []) for t in channel.get("recent_titles", [])]
    return titles[:MAX_CONTEXT_LINES]


def build_prompt(brand: str, languages: list[str], count: int, phrases: list[str], titles: list[str]) -> str:
    parts = [
        "Brand / channel and its audience:\n" + brand,
        f"Write {count} distinct YouTube search queries, spread across these languages: "
        + ", ".join(languages)
        + ". Write each query in its own language (not a translation word for word). "
        "Include variations: synonyms, sub-topics, techniques, tools, formats.",
    ]
    if phrases:
        parts.append("Questions viewers asked in comments (rewritten as phrases):\n- " + "\n- ".join(phrases))
    if titles:
        parts.append("Titles of recent videos already found relevant:\n- " + "\n- ".join(titles))
    return "\n\n".join(parts)


SCHEMA = object_schema(
    {
        "keywords": {
            "type": "array",
            "items": object_schema({"language": {"type": "string"}, "keyword": {"type": "string"}}),
        }
    }
)


def generate_keywords(cfg: Config, llm: LLM) -> list[Keyword]:
    brand = cfg.read_brand()
    phrases, titles = comment_phrases(cfg), relevant_titles(cfg)
    result = llm.json(SYSTEM, build_prompt(brand, cfg.languages, cfg.keyword_count, phrases, titles), SCHEMA)
    keywords: list[Keyword] = []
    seen = set()
    for item in result.get("keywords", []):
        language = str(item.get("language", "")).strip().lower()[:2]
        text = " ".join(str(item.get("keyword", "")).split())
        if language in cfg.languages and text and text.lower() not in seen:
            seen.add(text.lower())
            keywords.append(Keyword(language, text))
    if not keywords:
        raise ScoutError("The LLM returned no usable keywords. Check brand.txt and languages.")
    write_keywords(cfg.keywords_file, keywords, used_comments=bool(phrases), used_titles=bool(titles))
    return keywords


def write_keywords(path: Path, keywords: list[Keyword], used_comments: bool, used_titles: bool) -> None:
    sources = ["brand.txt"] + (["comment phrases"] if used_comments else []) + (["found titles"] if used_titles else [])
    header = [
        "# Generated by peer-scout from " + ", ".join(sources) + f" on {utc_now().date().isoformat()}.",
        "# Do not edit: this file is rewritten on every run. Edit brand.txt instead.",
        "# language | keyword",
    ]
    write_text(path, "\n".join(header + [f"{k.language} | {k.text}" for k in keywords]) + "\n")


def read_keywords(path: Path) -> list[Keyword]:
    if not path.exists():
        return []
    keywords = []
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.startswith("#") or "|" not in line:
            continue
        language, text = (part.strip() for part in line.split("|", 1))
        if language and text:
            keywords.append(Keyword(language, text))
    return keywords


def pick_keywords(cfg: Config, keywords: list[Keyword], count: int) -> list[Keyword]:
    """The ``count`` keywords searched least recently (never-searched first)."""
    last = read_json(cfg.state_dir / "keywords.json", {})
    order = sorted(enumerate(keywords), key=lambda pair: (last.get(pair[1].text, ""), pair[0]))
    return [keyword for _, keyword in order[:count]]


def mark_searched(cfg: Config, keyword: Keyword, day: str) -> None:
    path = cfg.state_dir / "keywords.json"
    last = read_json(path, {})
    last[keyword.text] = day
    write_json(path, last)
